type FullPolicy = 'reject' | 'drop-oldest';
class BoundedQueue<T> {
    private items: T[] = [];
    constructor(private readonly cap: number, private readonly policy: FullPolicy) {}
    tryPush(v: T): { ok: true; evicted?: T } | { ok: false; reason: 'full' } {
        if (this.items.length === this.cap) {
            if (this.policy === 'reject') return { ok: false, reason: 'full' };
            return { ok: true, evicted: this.items.shift() };   // the loss is returned, not hidden
        }
        this.items.push(v);
        return { ok: true };
    }
}
